css:
body{
font-family: Arial, Helvetica, sans-serif;
font-size:12px;
}

table{
width:100%;
border-collapse:collapse;
table-layout:fixed;
}

.header-table td{
border:1px solid #000;
padding:6px;
vertical-align:middle;
}

.logo-cell{
width:20%;
text-align:center;
}

.company-logo{
max-height:80px;
display:block;
margin:auto;
}

.title-cell{
width:55%;
text-align:center;
}

.meta-cell{
width:25%;
font-size:10px;
}

.cert-title{
font-size:16px;
font-weight:bold;
}

.cert-company{
font-size:11px;
}

.section-title{
font-weight:bold;
text-align:center;
background:#f2f2f2;
}

.small-text{
font-size:11px;
}

.intro-text{
text-align:justify;
line-height:1.5;
margin:15px 0;
}

.result-table th{
background:#f3f3f3;
font-weight:bold;
}

.result-ok{
color:#2e7d32;
font-weight:bold;
}

.result-bad{
color:#c62828;
font-weight:bold;
}

.signature-section{
margin-top:60px;
}

.signature-line{
border-top:1px solid #000;
text-align:center;
font-size:11px;
padding-top:6px;
}

.page-number:before{
content:counter(page);
}

.page-count:before{
content:counter(pages);
}

@media print{

thead{
display:table-header-group;
}

tr{
page-break-inside:avoid;
}

}
.footer-certificado{
    position: fixed;
    bottom: 0;
    left: 0;
    width: 100%;
    text-align: center;
    font-size: 10px;
    border-top: 1px solid #000;
    padding-top: 5px;
    background: white;
}
